@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products…"
           @bind="_searchText"
           @bind:event="oninput"
           @bind:after="OnSearchTextChangedAsync" />

    @if (_isLoading)
    {
        <div class="product-search-status">Searching…</div>
    }
    else if (_errorMessage is not null)
    {
        <div class="product-search-error">
            <span>@_errorMessage</span>
            <button @onclick="RetryAsync">Retry</button>
        </div>
    }
    else if (_hasSearched && _products.Count == 0)
    {
        <div class="product-search-status">No products found.</div>
    }

    @if (_products.Count > 0)
    {
        <div class="product-search-results">
            @foreach (var product in _products)
            {
                <div class="product-card" @onclick="() => SelectProduct(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" loading="lazy" />
                    <div class="product-card-body">
                        <h4>@product.Name</h4>
                        <span class="product-card-price">@product.Price.ToString("C")</span>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private string _searchText = string.Empty;
    private List<Product> _products = new();
    private bool _isLoading;
    private bool _hasSearched;
    private string? _errorMessage;

    private CancellationTokenSource? _debounceCts;
    private CancellationTokenSource? _searchCts;

    private async Task OnSearchTextChangedAsync()
    {
        // Cancel any pending debounce timer.
        _debounceCts?.Cancel();
        _debounceCts?.Dispose();
        _debounceCts = new CancellationTokenSource();
        var debounceToken = _debounceCts.Token;

        if (string.IsNullOrWhiteSpace(_searchText))
        {
            CancelInflightSearch();
            _products = new();
            _hasSearched = false;
            _errorMessage = null;
            _isLoading = false;
            return;
        }

        try
        {
            await Task.Delay(300, debounceToken);
        }
        catch (TaskCanceledException)
        {
            // User typed again before the debounce elapsed — nothing to do.
            return;
        }

        await ExecuteSearchAsync(_searchText);
    }

    private async Task ExecuteSearchAsync(string query)
    {
        // Cancel any in-flight search so the service stops working on stale results.
        CancelInflightSearch();
        _searchCts = new CancellationTokenSource();
        var ct = _searchCts.Token;

        _isLoading = true;
        _errorMessage = null;

        try
        {
            var results = await ProductService.SearchAsync(query, ct);

            // If this search was cancelled while awaiting, discard results.
            if (ct.IsCancellationRequested)
                return;

            _products = results;
            _hasSearched = true;
        }
        catch (OperationCanceledException)
        {
            // Search was intentionally cancelled — no error to show.
        }
        catch (Exception)
        {
            if (!ct.IsCancellationRequested)
            {
                _errorMessage = "Something went wrong. Please try again.";
            }
        }
        finally
        {
            if (!ct.IsCancellationRequested)
            {
                _isLoading = false;
            }
        }
    }

    private async Task RetryAsync()
    {
        if (!string.IsNullOrWhiteSpace(_searchText))
        {
            await ExecuteSearchAsync(_searchText);
        }
    }

    private void SelectProduct(Product product)
    {
        OnProductSelected.InvokeAsync(product);
    }

    private void CancelInflightSearch()
    {
        _searchCts?.Cancel();
        _searchCts?.Dispose();
        _searchCts = null;
    }

    public void Dispose()
    {
        _debounceCts?.Cancel();
        _debounceCts?.Dispose();
        CancelInflightSearch();
    }
}

